from __future__ import absolute_import

import logging
import time

from .common_page import CommonPage
from .panels.view import ViewPanel

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CertificateManagement(CommonPage):
    """
    The class corresponding to diagnostic page on selenium_coam_cu web, all operations under Certificate Management
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"Operator Certificates": OperatorCertificatesPage(driver, version),
                                   "Certificate Revocation List": CertificateRevocationListPage(driver,
                                                                                                version),
                                   "Automatic Management": AutomaticManagementPage(driver, version)}
        super(CertificateManagement, self).__init__(driver, version, self._instance_dict)


class OperatorCertificatesPage(object):
    """
    As a class will be called by Diagnostic, all operations Snapshot will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['medal', 'Operator Certificates']

    def __init__(self, driver, version):
        self._view_panel = OperatorCertificatesPageViewPanel(driver, version)

    def generate_certificate_signing(self, timeout):
        return self._view_panel.generate_certificate_signing(timeout)

    def install_end_entity_certificate_from_local(self, certificate_path, timeout):
        """
        This keyword will install and return the status of installation of  end entity certificate
        :param certificate_path: str, location of certificate in present system
        :param timeout: int, timeout for the element be available to click

        :return: str, status of end entity certificate  install
        """
        return self._view_panel.install_end_entity_certificate_from_local(certificate_path, timeout)

    def install_additional_ca_certificate_from_local(self, certificate_path, timeout):
        """
        This keyword will install and return the status of installation of  additional ca certificate
        :param certificate_path: str, location of certificate in present system
        :param timeout: int, timeout for the element be available to click

        :return: str, status of additional ca certificate  install
        """
        return self._view_panel.install_additional_ca_certificate_from_local(certificate_path, timeout)

    def get_certificates(self, serial_number, timeout):
        """
        This keyword will return the details of the certificate stored with given serial number
        :param serial_number: str, serial number of the certificate that need to be returned
        :param timeout: int, timeout for the element be available to click
        :return: dict, details of the certificate
        """
        return self._view_panel.get_certificates(serial_number, timeout)

    def delete_certificate(self, serial_number, timeout):
        """
        This keyword will delete the certificate stored with given serial number
        :param serial_number: str, serial number of the certificate that need to be deleted
        :param timeout: int, timeout for the element be available to click
        :return: str, status of the delete given certificate
        """
        return self._view_panel.delete_certificate(serial_number, timeout)

    def restore_default_certificates(self, timeout):
        """
        This keyword will restore all the certificates to default values

        :param timeout: int, timeout for the element be available to click
        :return: str, status of the restoration certificates to default values
        """
        return self._view_panel.restore_default_certificates(timeout)


