class OperatorCertificatesPageViewPanel(ViewPanel):
    def __init__(self, driver, version):
        self.driver = driver
        super(OperatorCertificatesPageViewPanel, self).__init__(driver, version)

    def generate_certificate_signing(self, timeout):
        time.sleep(3)
        self.click_enabled_element(self.locator.GENERATE_CERTIFICATE_BUTTON, timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("Generate certificate signing request "
                                                                   "operation started"), timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("Generate certificate signing request "
                                                                   "operation finished"), timeout)
        self.wait_for_invisibility(
            self.locator.TOAST_MESSAGE.format("Generate certificate signing request operation finished"),
            timeout)
        return self.get_attribute("//textarea", "value")

    def install_end_entity_certificate_from_local(self, certificate_path, timeout):
        """
         This keyword will install and return the status of installation of  end entity certificate

        :param certificate_path: str, location of certificate in present system
        :param timeout: int, timeout for the element be available to click
        :return: str, status of end entity certificate install
        """
        self.select_radiobox(self.locator.END_ENTITY_RADIO_BUTTON, timeout)
        self.upload(self.locator.LOAD_CERTIFICATE_FILE_XPATH, certificate_path, timeout)
        self.click_enabled_element(self.locator.INSTALL_CERTIFICATE_BUTTON, timeout)
        return self._verify_toast_message_return_status("Install certificate operation started", timeout)

    def install_additional_ca_certificate_from_local(self, certificate_path, timeout):
        """
         This keyword will install and return the status of installation of  additional ca certificate

        :param certificate_path: str, location of certificate in present system
        :param timeout: int, timeout for the element be available to click

        :return: str, status of additional ca certificate  install
        """
        self.select_radiobox(self.locator.ADDITIONAL_CA_RADIO_BUTTON, timeout)

        self.upload(self.locator.LOAD_CERTIFICATE_FILE_XPATH, certificate_path, timeout)
        self.click_enabled_element(self.locator.INSTALL_CERTIFICATE_BUTTON, timeout)
        return self._verify_toast_message_return_status("Install certificate operation started", timeout)

    def restore_default_certificates(self, timeout):
        """
       This keyword will restore all the certificates to default values

        :param timeout: int, timeout for the element be available to click
        :return: str, status of the restoration certificates to default values
        """
        self.click_enabled_element(self.locator.RESTORE_DEFAULT_CERTIFICATE, timeout)
        return self._verify_toast_message_return_status("Restore certificates operation started", timeout)

    def delete_certificate(self, serial_number, timeout):
        """
        This keyword will delete the certificate stored with given serial number
        :param serial_number: str, serial number of the certificate that need to be deleted
        :param timeout: int, timeout for the element be available to click
        :return: str, status of the delete given certificate
        """
        certificate_header = self.get_fields_info_from_row(self.locator.OPERATOR_CERTIFICATES_TABLE_HEADER, timeout)
        serial_number_index = certificate_header.index("Serial number") + 1
        delete_action_index = certificate_header.index("Action") + 1
        while True:
            if self.element_exists(self.locator.DELETE_CERTIFICATE_IMAGE.format(serial_number_index, serial_number,
                                                                                delete_action_index), timeout=3):
                delete_status = self.get_attribute(self.locator.DELETE_CERTIFICATE_IMAGE.format(serial_number_index,
                                                                                                serial_number,
                                                                                                delete_action_index),
                                                   "title")
                if delete_status != "Delete certificate":
                    return delete_status
                self.click_enabled_element(
                    self.locator.DELETE_CERTIFICATE_IMAGE.format(serial_number_index, serial_number,
                                                                 delete_action_index), timeout)
                break
            if self._navigate_next_page(timeout):
                continue
            return "No serial_number number {} found in the table".format(serial_number)
        return self._verify_toast_message_return_status("Delete certificate operation started", timeout)

    def get_certificates(self, serial_number, timeout):
        """
         This keyword will return the details of the certificate stored with given serial number
        :param serial_number: str, serial number of the certificate that need to be returned
        :param timeout: int, timeout for the element be available to click
        :return: dict, details of the certificate
        """
        certificate_header = self.get_fields_info_from_row(self.locator.OPERATOR_CERTIFICATES_TABLE_HEADER, timeout)
        serial_number_index = certificate_header.index("Serial number") + 1
        certificate_details = []
        while True:
            if self.element_exists(self.locator.GET_CERTIFICATE_ROW.format(serial_number_index, serial_number),
                                   timeout=3):
                certificate_details = self.get_fields_info_from_row(self.locator.GET_CERTIFICATE_ROW.
                                                                    format(serial_number_index,
                                                                           serial_number), timeout)
                certificate_details.insert(0, self.get_attribute(
                    self.locator.GET_CERTIFICATE_ROW.format(serial_number_index, serial_number) + "[1]//i",
                    "title", timeout))
                break
            if self._navigate_next_page(timeout):
                continue
            return "No serial_number number {} found in the table".format(serial_number)
        return {certificate_header[i]: certificate_details[i] for i in range(len(certificate_header))}

    def _navigate_next_page(self, timeout):
        if not self.element_exists(self.locator.RIGHT_NAVIGATOR_STATUS, timeout=3):
            self.click_enabled_element(self.locator.RIGHT_NAVIGATOR_XPATH, timeout)
            return True
        return False


class CertificateRevocationListPageViewPanel(ViewPanel):
    def __init__(self, driver, version):
        self.driver = driver
        super(CertificateRevocationListPageViewPanel, self).__init__(driver, version)

    def get_certificate_revocation_list(self, timeout):
        """
         This keyword will update certificate revocation list , collect and return all the table content
        :param timeout: int, timeout for the element be available to click
        :return: list , list of dict of the certificate revocation list table content
        """
        self.click_enabled_element(self.locator.UPDATE_CERTIFICATE_REVOCATION_LIST_BUTTON, timeout)
        result = [{"update status": self._verify_toast_message_return_status(
            "Update certificate revocation list request operation started", timeout)}]
        if self.element_exists(self.locator.CERTIFICATE_REVOCATION_LIST_EMPTY_TABLE, timeout=3):
            result.append({"data": "No data"})
            return result
        header = self.get_fields_info_from_row(self.locator.CERTIFICATE_REVOCATION_LIST_TABLE_HEADER, timeout)
        number_of_pages = self.get_text(self.locator.PAGINATION_PAGE_NUMBER, timeout).split(" ")[-1]
        for page in range(1, int(number_of_pages) + 1):
            number_of_rows = self.get_all_matching_elements(self.locator.CERTIFICATE_REVOCATION_LIST_TABLE_BODY_ROWS)
            for row in range(1, len(number_of_rows) + 1):
                row_list = self.get_text_from_all_matching_elements(
                    self.locator.CERTIFICATE_REVOCATION_LIST_TABLE_BODY_CELLS.format(row))
                result.append({header[i]: row_list[i] for i in range(len(header))})
            if page == int(number_of_pages):
                break
            else:
                self.click_enabled_element(self.locator.PAGE_RIGHT_NAVIGATOR_CSS_PATH, timeout)
                time.sleep(3)
        return result


class AutomaticManagementPageViewPanel(ViewPanel):
    def __init__(self, driver, version):
        self.driver = driver
        super(AutomaticManagementPageViewPanel, self).__init__(driver, version)

    def update_cmp_server_setting(self, reference_number, pre_shared_key, timeout):
        """
        This keyword will update the cmp sever settings and return the status of update

        :param reference_number: str, reference number of cmp server
        :param pre_shared_key:str, pre_shared key of cmp server
        :param timeout: int, timeout for the element be available to click
        :return:str, Status of CMP server update
        """
        self.insert_text_to_enable_element(self.locator.REFERENCE_NUMBER_INPUT, reference_number, timeout)
        self.insert_text_to_enable_element(self.locator.PRE_SHARED_KEY_INPUT, pre_shared_key, timeout)
        self.click_enabled_element(self.locator.SAVE_CMP_SERVER_SETTING_BUTTON, timeout)
        return self._verify_toast_message_return_status("Update CMP settings operation started", timeout)

    def get_cmp_state(self, timeout):
        """
         This keyword will return state of CMP server update

        :param timeout: int, timeout for the element be available to click
        :return:str, state of CMP server update
        """
        self.wait_for_visibility(self.locator.CMP_SERVER_STATUS, timeout)
        return self.get_text_from_all_matching_elements(self.locator.CMP_SERVER_STATUS)[-1]

    def initialize_certificates(self, timeout):
        """
         This keyword will initialize certificates for CMP server update and status
        :param timeout: int, timeout for the element be available to click
        :return:str, Status of initialize certificates for CMP server
        """
        self.click_enabled_element(self.locator.INITIALIZE_CERTIFICATE_BUTTON, timeout)
        return self._verify_toast_message_return_status("Initialize Certificates operation started", timeout)

    def cmp_key_update(self, timeout):
        """
         This keyword will click cmp Key Update button return status
        :param timeout: int, timeout for the element be available to click
        :return:str, Status of click cmp Key Update button
        """
        self.click_enabled_element(self.locator.CMP_KEY_UPDATE_BUTTON, timeout)
        return self._verify_toast_message_return_status("Update CMP key operation started", timeout)
